import { useFrame } from '@react-three/fiber'
import { BallCollider, type RapierRigidBody, RigidBody } from '@react-three/rapier'
import {
  inScenePass,
  lazyModule,
  rng,
  scenePass,
  sub,
  useNodeRenderer,
  useWorld,
  type Vec3,
  type WorldComponentProps,
} from '@runek/core'
import { type RefObject, useEffect, useMemo, useRef } from 'react'
import {
  AdditiveBlending,
  BufferAttribute,
  BufferGeometry,
  Color,
  type Group,
  HalfFloatType,
  InstancedBufferAttribute,
  type Mesh,
  PerspectiveCamera,
  Plane,
  ShaderMaterial,
  type Texture,
  Vector2,
  Vector3,
  Vector4,
  type WebGLRenderer,
  WebGLRenderTarget,
} from 'three'
import { Sign } from './Sign'

// The WebGPU (TSL) twins of the shaders below, loaded only under a node renderer.
const riftNodes = lazyModule(() => import('./nodes/rift'))

export interface RiftProps extends WorldComponentProps {
  /**
   * Where the other end stands (the foot of its rift), in world coordinates. Each end shows
   * the other live through its opening, and walking into either carries you to the other.
   * Default: 8 units behind `position`.
   */
  destination?: Vec3
  /** Euler rotation of the far end, in radians: which way its caption faces. Default `rotation`. */
  destinationRotation?: Vec3
  /** Floating caption above the rift at `position` (e.g. the name of where it leads). */
  label?: string
  /** Floating caption above the rift at `destination`. */
  returnLabel?: string
  /** Radius of each opening, in units. The ragged edge breathes around it. */
  radius?: number
  /** Tint for the rims and glitter. Unset, the rims are an iridescent pink, violet and cyan film. */
  color?: string
  /**
   * Open both rifts and let them carry travelers. When false they shrink to small shimmering
   * bubbles and stay inert; flipping it to true tears them open. Default true.
   */
  active?: boolean
  /** Called after a traveler is carried through, with the foot of the end they came out of. */
  onTravel?: (arrival: Vec3) => void
}

// The quad reaches past the edge so the halo and the shed glitter have room; in multiples of `radius`.
const EXTENT = 1.7
// How far open the rifts sit while inactive: small bubbles, in multiples of `radius`.
const CLOSED = 0.18
const MOTES = 700
// The far view renders at this fraction of the viewer's resolution: the soap-film rim and the
// lensing hide the softness, and it quarters the fill.
const VIEW_SCALE = 0.5
// How big an opening must be on screen (its radius, in CSS pixels) to show the far end live.
// Smaller or more distant rifts show a shimmer instead, so they cost no second render.
const LIVE_SIZE = 40
// Far-view targets kept per rift end, one per viewer size (the screen, or each lens view).
const MAX_TARGETS = 4

// The edge of a rift, shared by the window and the glitter so sparks are born right on it.
const EDGE = /* glsl */ `
uniform float uTime;
uniform float uSeed;
uniform float uOpen;
uniform float uTurb;

float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
float noise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
             mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm(vec2 p) {
  float v = 0.0, a = 0.5;
  for (int i = 0; i < 3; i++) { v += a * noise(p); p = p * 2.07 + 13.3; a *= 0.5; }
  return v;
}
// Sampling noise on the unit circle keeps the outline seamless all the way round.
float edge(vec2 dir) {
  float ragged = smoothstep(${CLOSED.toFixed(2)}, 1.0, uOpen) * uTurb;
  float slow = fbm(dir * 1.4 + uSeed + uTime * 0.11) - 0.5;
  float fine = noise(dir * 6.0 - uSeed + uTime * 0.7) - 0.5;
  return uOpen * (0.82 + slow * 0.55 * ragged + fine * 0.1 * ragged);
}
// Thin-film iridescence, held to the pink / violet / cyan end of the spectrum.
vec3 film(float x) {
  x = fract(x);
  vec3 c = mix(vec3(1.0, 0.08, 0.55), vec3(0.35, 0.12, 1.0), smoothstep(0.0, 0.33, x));
  c = mix(c, vec3(0.1, 0.75, 1.0), smoothstep(0.33, 0.66, x));
  return mix(c, vec3(1.0, 0.08, 0.55), smoothstep(0.66, 1.0, x));
}`

// Camera-facing around the rift's center, so it reads as a hole in space from any side.
const WINDOW_VERTEX = /* glsl */ `
uniform float uR;
varying vec2 vP;
void main() {
  vP = position.xy / uR;
  vec4 mv = modelViewMatrix * vec4(0.0, 0.0, 0.0, 1.0);
  mv.xy += position.xy * length(modelMatrix[0].xyz);
  gl_Position = projectionMatrix * mv;
}`

const WINDOW_FRAGMENT = /* glsl */ `
${EDGE}
uniform sampler2D uView;
uniform vec4 uViewport;
uniform float uLive;
uniform vec3 uTint;
uniform float uTintMix;
varying vec2 vP;

void main() {
  float r = length(vP);
  vec2 dir = vP / max(r, 1e-4);
  float d = r - edge(dir);
  float s = mix(0.45, 1.0, uOpen);
  float inside = 1.0 - smoothstep(-0.006 * s, 0.006 * s, d);

  // The far end is sampled in screen space, so it moves with the viewer like a real opening;
  // near the rim it bends outward a touch, like light through a soap film.
  float lens = exp(min(d, 0.0) / (0.05 * s));
  float a = atan(vP.y, vP.x);
  vec3 tint = mix(film(a * 0.32 + d * 1.2 + uTime * 0.08), uTint, uTintMix);

  // Too small on screen to be worth a second render: a slow shimmer stands in for the far end.
  vec3 far = tint * (0.12 + 0.18 * fbm(vP * 2.5 + uSeed + uTime * 0.15));
  if (uLive > 0.0) {
    vec2 uv = (gl_FragCoord.xy - uViewport.xy) / uViewport.zw - dir * lens * 0.012;
    vec3 view = texture2D(uView, uv).rgb;
#ifdef TONE_MAPPING
    view = toneMapping(view);
#endif
    far = mix(far, view, uLive);
  }
  far = mix(far, tint * 0.5, lens * 0.25);

  // The rim flickers along its length like plasma rather than glowing as one even line.
  float plasma = 0.55 + 0.9 * noise(dir * 14.0 + vec2(uTime * 1.7, -uTime * 1.3) + uSeed);
  float core = exp(-pow(d / (0.02 * s), 2.0)) * plasma;
  float glow = exp(-abs(d) / (0.04 * s)) * plasma;
  float halo = step(0.0, d) * exp(-pow(d / (0.2 * s), 2.0)) * 0.16;

  // Glints that twinkle in a band hugging the rim, mostly on the outside.
  vec2 g = vP * 40.0;
  vec2 id = floor(g);
  float h = hash(id + uSeed);
  vec2 off = (vec2(hash(id + 3.1), hash(id + 7.7)) - 0.5) * 0.6;
  float twinkle = pow(0.5 + 0.5 * sin(uTime * (2.0 + h * 5.0) + h * 40.0), 6.0);
  float band = exp(-pow((d - 0.05 * s) / (0.1 * s), 2.0));
  float glint = step(0.6, h) * twinkle * smoothstep(0.14, 0.0, length(fract(g) - 0.5 - off)) * band;

  // Fade everything out before the edge of the quad so it never shows as a square.
  float fade = 1.0 - smoothstep(${(EXTENT * 0.75).toFixed(2)}, ${EXTENT.toFixed(2)}, r);
  vec3 light = (tint * (glow * 1.1 + halo) + vec3(1.0) * core * 1.8
             + mix(vec3(1.0), tint, 0.4) * glint * 2.5) * fade;

  // Premultiplied: the window is opaque, the rim adds over whatever is behind it.
  float alpha = max(inside, clamp((core * 0.6 + glow * 0.6 + halo * 1.2 + glint * 0.5) * fade, 0.0, 1.0));
  gl_FragColor = vec4(far * inside + light, alpha);
  #include <colorspace_fragment>
}`

const MOTE_VERTEX = /* glsl */ `
${EDGE}
uniform float uR;
uniform float uSize;
uniform float uHalfHeight;
uniform vec3 uTint;
uniform float uTintMix;
attribute vec3 aMote;
attribute vec3 aKind;
varying vec3 vColor;
void main() {
  float life = fract(aMote.y + uTime * aMote.z);
  vec2 dir = vec2(cos(aMote.x), sin(aMote.x));
  // Born on the rim, then shed outward (or, for a few, inward) and settling like glitter.
  float r = edge(dir) + aKind.z * life * mix(0.4, 1.0, uOpen);
  float a = aMote.x + life * 0.35;
  vec2 p = vec2(cos(a), sin(a)) * r - vec2(0.0, 0.3 * life * life * uOpen);
  vec4 mv = modelViewMatrix * vec4(0.0, 0.0, 0.0, 1.0);
  float scale = length(modelMatrix[0].xyz);
  mv.xy += p * uR * scale;
  gl_Position = projectionMatrix * mv;

  float fade = smoothstep(0.0, 0.08, life) * (1.0 - smoothstep(0.55, 1.0, life));
  float twinkle = 0.35 + 0.65 * pow(0.5 + 0.5 * sin(uTime * (5.0 + aKind.y * 9.0) + aMote.y * 60.0), 3.0);
  vColor = mix(vec3(1.0), mix(film(aKind.y), uTint, uTintMix), 0.55) * fade * twinkle;
  gl_PointSize = uSize * scale * (0.4 + aKind.x) * projectionMatrix[1][1] * uHalfHeight / -mv.z;
}`

const MOTE_FRAGMENT = /* glsl */ `
varying vec3 vColor;
void main() {
  float d = length(gl_PointCoord - 0.5);
  float spark = pow(smoothstep(0.5, 0.0, d), 2.0);
  gl_FragColor = vec4(vColor * spark * 1.6, 1.0);
}`

const POOL_VERTEX = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`

const POOL_FRAGMENT = /* glsl */ `
uniform vec3 uColor;
uniform float uOpen;
varying vec2 vUv;
void main() {
  float r = length(vUv - 0.5) * 2.0;
  float a = pow(max(1.0 - r, 0.0), 2.2) * 0.4 * uOpen;
  gl_FragColor = vec4(uColor * a, 1.0);
}`

type Uniform<T> = { value: T }
interface Shared {
  uTime: Uniform<number>
  uOpen: Uniform<number>
  uTurb: Uniform<number>
}

/**
 * A pair of linked rifts torn in the air: ragged, breathing openings edged in iridescent light
 * and shedding glitter. Each shows the other end live and in parallax, exactly as you'd see it
 * standing there, and walking into either carries you through to the other, momentum and all.
 * Both ends are places in the same world, so use it for shortcuts you can walk (across a map,
 * up a tower, between rooms); for travel to another world or page, use `Portal`. The look is
 * procedural and asset-free (the seed shapes the edges and the glitter). Each open rift big
 * enough on screen to show the far end live costs a second render of the scene, at half
 * resolution and clipped to the rift's footprint; a small or distant one shows a shimmer.
 */
export function Rift({
  position = [0, 0, 0],
  rotation = [0, 0, 0],
  seed = 1,
  destination,
  destinationRotation,
  label,
  returnLabel,
  radius = 1.5,
  color,
  active = true,
  onTravel,
}: RiftProps) {
  const { unit, player, playerControl } = useWorld()
  const R = radius * unit
  const there: Vec3 = destination ?? [position[0], position[1], position[2] - 8 * unit]

  const shared = useMemo<Shared>(
    () => ({ uTime: { value: 0 }, uOpen: { value: CLOSED }, uTurb: { value: 1 } }),
    [],
  )
  const near = useRef<Group>(null)
  const far = useRef<Group>(null)
  const nearCore = useRef<Group>(null)
  const farCore = useRef<Group>(null)
  const ends = useMemo(() => [near, far], [])
  const arrivals = useMemo(() => [new Set<number>(), new Set<number>()], [])

  useFrame(({ clock }, dt) => {
    const goal = active ? 1 : CLOSED
    const open = shared.uOpen.value
    shared.uOpen.value = open + (goal - open) * (1 - Math.exp(-dt * 1.8))
    shared.uTurb.value = 1 + 2.5 * Math.abs(goal - open)
    shared.uTime.value = clock.elapsedTime
  })

  // Carry a body from one end to the matching spot at the other, keeping its velocity. The avatar
  // goes through the player's teleport, which takes its camera along.
  const travel = (
    body: RapierRigidBody,
    from: RefObject<Group | null>,
    to: RefObject<Group | null>,
    arrival: Vec3,
    landing: Set<number>,
  ) => {
    if (!from.current || !to.current) return
    const offset = to.current
      .getWorldPosition(new Vector3())
      .sub(from.current.getWorldPosition(new Vector3()))
    const t = body.translation()
    const was = new Vector3(t.x, t.y, t.z)
    const dest = was.clone().add(offset)
    landing.add(body.handle)

    const eye = player?.current?.getWorldPosition(new Vector3())
    const control = playerControl?.current
    if (control && eye && eye.distanceToSquared(was) < 4 * unit * unit) {
      control.teleport([dest.x, dest.y, dest.z], { keepVelocity: true })
    } else {
      body.setTranslation(dest, true)
    }
    onTravel?.(arrival)
  }

  const common = { R, unit, shared, color, active, ends }
  return (
    <>
      <RiftEnd
        {...common}
        end={near}
        core={nearCore}
        otherCore={farCore}
        at={position}
        rotation={rotation}
        seed={sub(seed, 0)}
        label={label}
        arrivals={arrivals[0]}
        onEnter={(body) => travel(body, nearCore, farCore, there, arrivals[1])}
      />
      <RiftEnd
        {...common}
        end={far}
        core={farCore}
        otherCore={nearCore}
        at={there}
        rotation={destinationRotation ?? rotation}
        seed={sub(seed, 1)}
        label={returnLabel}
        arrivals={arrivals[1]}
        onEnter={(body) => travel(body, farCore, nearCore, position, arrivals[0])}
      />
    </>
  )
}

const bufferSize = new Vector2()

const smoothstep = (x: number, from: number, to: number) => {
  const t = Math.min(Math.max((x - from) / (to - from), 0), 1)
  return t * t * (3 - 2 * t)
}

/** This end's far-view target for a viewer `w` x `h` pixels, kept per size so a lens's views
 *  of different sizes never resize one target back and forth. */
function viewTarget(targets: Map<string, WebGLRenderTarget>, w: number, h: number) {
  const key = `${w}x${h}`
  let target = targets.get(key)
  if (target) {
    targets.delete(key)
  } else {
    target = new WebGLRenderTarget(
      Math.max(1, Math.round(w * VIEW_SCALE)),
      Math.max(1, Math.round(h * VIEW_SCALE)),
      { type: HalfFloatType, samples: 4 },
    )
    const oldest = targets.size >= MAX_TARGETS ? targets.keys().next().value : undefined
    if (oldest !== undefined) {
      targets.get(oldest)?.dispose()
      targets.delete(oldest)
    }
  }
  targets.set(key, target)
  return target
}

interface RiftEndProps {
  end: RefObject<Group | null>
  /** The center of this rift and of the other one; the view and travel follow their world positions. */
  core: RefObject<Group | null>
  otherCore: RefObject<Group | null>
  ends: RefObject<Group | null>[]
  at: Vec3
  rotation: Vec3
  R: number
  unit: number
  seed: number
  label?: string
  color?: string
  active: boolean
  shared: Shared
  arrivals: Set<number>
  onEnter: (body: RapierRigidBody) => void
}

function RiftEnd({
  end,
  core,
  otherCore,
  ends,
  at,
  rotation,
  R,
  unit,
  seed,
  label,
  color,
  active,
  shared,
  arrivals,
  onEnter,
}: RiftEndProps) {
  const pane = useRef<Mesh>(null)

  const view = useMemo(() => {
    const camera = new PerspectiveCamera()
    camera.matrixAutoUpdate = false
    camera.matrixWorldAutoUpdate = false
    return {
      camera,
      targets: new Map<string, WebGLRenderTarget>(),
      uView: { value: null as Texture | null },
      uLive: { value: 0 },
      viewport: new Vector4(),
      clip: new Plane(),
      forward: new Vector3(),
      point: new Vector3(),
      here: new Vector3(),
      there: new Vector3(),
    }
  }, [])
  useEffect(
    () => () => {
      for (const target of view.targets.values()) target.dispose()
      view.targets.clear()
    },
    [view],
  )

  const tint = useMemo(() => new Color(color ?? '#ffffff'), [color])
  const tintMix = color ? 0.65 : 0
  const own = useMemo(() => ({ uSeed: { value: rng(seed)() * 100 } }), [seed])
  const nodes = useNodeRenderer() ? riftNodes() : null

  const windowPane = useMemo(() => {
    const uniforms = {
      ...shared,
      ...own,
      uR: { value: R },
      uView: view.uView,
      uViewport: { value: view.viewport },
      uLive: view.uLive,
      uTint: { value: tint },
      uTintMix: { value: tintMix },
    }
    if (nodes) return nodes.windowMaterial(uniforms, CLOSED, EXTENT)
    const material = new ShaderMaterial({
      vertexShader: WINDOW_VERTEX,
      fragmentShader: WINDOW_FRAGMENT,
      uniforms,
      transparent: true,
      premultipliedAlpha: true,
      depthWrite: false,
    })
    return { material, view: null }
  }, [shared, own, R, view, tint, tintMix, nodes])
  const material = windowPane.material

  const motes = useMemo(() => {
    const r = rng(sub(seed, 1))
    const mote = new Float32Array(MOTES * 3)
    const kind = new Float32Array(MOTES * 3)
    for (let i = 0; i < MOTES; i++) {
      mote[i * 3] = r() * Math.PI * 2
      mote[i * 3 + 1] = r()
      mote[i * 3 + 2] = 0.12 + r() * 0.3
      kind[i * 3] = r() * r()
      kind[i * 3 + 1] = r()
      kind[i * 3 + 2] = r() < 0.2 ? -0.08 - r() * 0.12 : 0.1 + r() * 0.55
    }
    const uniforms = {
      ...shared,
      ...own,
      uR: { value: R },
      uSize: { value: 0.05 * R },
      uHalfHeight: { value: 400 },
      uTint: { value: tint },
      uTintMix: { value: tintMix },
    }
    if (nodes) {
      // WebGPU draws points a pixel wide: instanced quads instead.
      const geometry = nodes.pointQuads(MOTES, {
        aMote: new InstancedBufferAttribute(mote, 3),
        aKind: new InstancedBufferAttribute(kind, 3),
      })
      return {
        geometry,
        material: nodes.riftMotesMaterial(uniforms, CLOSED),
        uniforms,
        quads: true,
      }
    }
    const geometry = new BufferGeometry()
    geometry.setAttribute('position', new BufferAttribute(new Float32Array(MOTES * 3), 3))
    geometry.setAttribute('aMote', new BufferAttribute(mote, 3))
    geometry.setAttribute('aKind', new BufferAttribute(kind, 3))
    const material = new ShaderMaterial({
      vertexShader: MOTE_VERTEX,
      fragmentShader: MOTE_FRAGMENT,
      uniforms,
      transparent: true,
      blending: AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    })
    return { geometry, material, uniforms, quads: false }
  }, [shared, own, R, seed, tint, tintMix, nodes])

  const pool = useMemo(() => {
    const uniforms = { uColor: { value: new Color(color ?? '#c86bff') }, uOpen: shared.uOpen }
    return nodes
      ? nodes.poolMaterial(uniforms, 0.4)
      : new ShaderMaterial({
          vertexShader: POOL_VERTEX,
          fragmentShader: POOL_FRAGMENT,
          uniforms,
          transparent: true,
          blending: AdditiveBlending,
          depthWrite: false,
          toneMapped: false,
        })
  }, [color, shared, nodes])

  useFrame(({ size, viewport }) => {
    motes.uniforms.uHalfHeight.value = (size.height * viewport.dpr) / 2
  })

  const windowView = windowPane.view
  // Draw the other end just before this window draws, with whatever camera is drawing it, so
  // the view never lags the viewer by a frame and is skipped whenever the rift is culled or too
  // small on screen to matter.
  useEffect(() => {
    const mesh = pane.current
    if (!mesh) return
    mesh.onBeforeRender = (renderer, scene, camera) => {
      // Never inside another pass that draws the scene (another rift's view, a mirror): a rift
      // seen there keeps the frame it last drew rather than recursing.
      if (inScenePass() || !core.current || !otherCore.current) return
      core.current.getWorldPosition(view.here)
      const scale = core.current.getWorldScale(view.point).x
      // `WebGLRenderer` keeps viewport and depth-mask state a nested render disturbs;
      // `WebGPURenderer` draws each render in its own pass, so it has neither, and counts rows
      // from the top.
      const gl = (renderer as { isWebGLRenderer?: boolean }).isWebGLRenderer
        ? (renderer as WebGLRenderer)
        : null
      if (gl) gl.getCurrentViewport(view.viewport)
      else {
        const drawing = renderer.getRenderTarget()
        if (drawing) view.viewport.set(0, 0, drawing.width, drawing.height)
        else {
          renderer.getDrawingBufferSize(bufferSize)
          view.viewport.set(0, 0, bufferSize.x, bufferSize.y)
        }
      }
      const w = view.viewport.z
      const h = view.viewport.w

      // The opening's radius on screen, in CSS pixels; fade the live view in as it grows.
      const c = view.point.copy(view.here).applyMatrix4(camera.matrixWorldInverse)
      const p = camera.projectionMatrix.elements
      const radius = R * scale
      const px =
        -c.z > radius ? (((radius * p[5]) / -c.z) * (h / 2)) / renderer.getPixelRatio() : Infinity
      view.uLive.value = smoothstep(px, LIVE_SIZE * 0.7, LIVE_SIZE)
      if (view.uLive.value === 0) return

      otherCore.current.getWorldPosition(view.there)
      const target = viewTarget(view.targets, w, h)
      view.uView.value = target.texture
      if (windowView) windowView.value = target.texture
      const previous = renderer.getRenderTarget()
      const autoClear = renderer.autoClear
      const xr = renderer.xr.enabled
      const shadows = renderer.shadowMap.autoUpdate
      const planes = renderer.clippingPlanes

      // The viewer's camera, carried to the other end.
      const eye = view.camera
      // In the drawing camera's clip space (WebGPU's depth runs 0..1), or the renderer would
      // rebuild the copied projection from the eye's own `fov`.
      eye.coordinateSystem = camera.coordinateSystem
      eye.projectionMatrix.copy(camera.projectionMatrix)
      eye.projectionMatrixInverse.copy(camera.projectionMatrixInverse)
      eye.matrixWorld.copy(camera.matrixWorld)
      const m = eye.matrixWorld.elements
      m[12] += view.there.x - view.here.x
      m[13] += view.there.y - view.here.y
      m[14] += view.there.z - view.here.z
      eye.matrixWorldInverse.copy(eye.matrixWorld).invert()

      // Only shade the pixels this rift covers on screen.
      const extent = R * EXTENT * scale
      if (-c.z > extent) {
        const k = target.width / w
        const rx = ((extent * p[0]) / -c.z) * (w / 2)
        const ry = ((extent * p[5]) / -c.z) * (h / 2)
        c.applyMatrix4(camera.projectionMatrix)
        const x = Math.max(0, Math.floor(((c.x * 0.5 + 0.5) * w - rx) * k))
        const tall = Math.ceil(2 * ry * k)
        const up = Math.max(0, Math.floor(((c.y * 0.5 + 0.5) * h - ry) * k))
        const y = gl ? up : Math.max(0, target.height - up - tall)
        target.scissor.set(x, y, Math.ceil(2 * rx * k), tall)
        target.scissorTest = true
      } else {
        target.scissorTest = false
      }

      // Cut away whatever stands between the carried camera and the far rift (a wall the viewer
      // isn't actually behind), keeping a rift's radius of what's just in front of it.
      view.forward.set(-m[8], -m[9], -m[10]).normalize()
      view.point.copy(view.there).addScaledVector(view.forward, -R * scale)
      view.clip.setFromNormalAndCoplanarPoint(view.forward, view.point)

      for (const e of ends) if (e.current) e.current.visible = false
      renderer.xr.enabled = false
      renderer.shadowMap.autoUpdate = false
      renderer.clippingPlanes = [view.clip]
      renderer.setRenderTarget(target)
      gl?.state.buffers.depth.setMask(true)
      if (gl && !autoClear) renderer.clear()
      if (!gl) renderer.autoClear = true
      scenePass(() => renderer.render(scene, eye))
      renderer.autoClear = autoClear
      renderer.clippingPlanes = planes
      renderer.shadowMap.autoUpdate = shadows
      renderer.xr.enabled = xr
      renderer.setRenderTarget(previous)
      gl?.state.viewport(view.viewport)
      for (const e of ends) if (e.current) e.current.visible = true
    }
    return () => {
      mesh.onBeforeRender = () => {}
    }
  }, [view, ends, core, otherCore, R, windowView])

  const extent = R * EXTENT

  return (
    <RigidBody type="fixed" colliders={false} position={at} rotation={rotation}>
      {/* A sensor filling the opening, the same from every side. Only dynamic bodies (the
          avatar, loose props) travel; one that just arrived isn't sent back until it steps out. */}
      <BallCollider
        sensor
        args={[Math.max(R * 0.8, 0.6 * unit)]}
        position={[0, R, 0]}
        onIntersectionEnter={({ other: o }) => {
          const body = o.rigidBody
          if (!active || !body?.isDynamic() || arrivals.has(body.handle)) return
          onEnter(body)
        }}
        onIntersectionExit={({ other: o }) => {
          if (o.rigidBody) arrivals.delete(o.rigidBody.handle)
        }}
      />

      <group ref={end}>
        <group ref={core} position={[0, R, 0]}>
          <mesh ref={pane} material={material} renderOrder={1}>
            <planeGeometry args={[extent * 2, extent * 2]} />
          </mesh>
          {motes.quads ? (
            <mesh
              geometry={motes.geometry}
              material={motes.material}
              frustumCulled={false}
              renderOrder={2}
            />
          ) : (
            <points
              geometry={motes.geometry}
              material={motes.material}
              frustumCulled={false}
              renderOrder={2}
            />
          )}
        </group>

        <mesh position={[0, 0.02 * unit, 0]} rotation={[-Math.PI / 2, 0, 0]} material={pool}>
          <planeGeometry args={[R * 2.6, R * 2.6]} />
        </mesh>

        {label && (
          <Sign position={[0, R * 2 + 0.7 * unit, 0]} size={0.6} color={color ?? '#e9b8ff'} glow>
            {label}
          </Sign>
        )}
      </group>
    </RigidBody>
  )
}

import { AdditiveBlending, type Color, DataTexture, type Texture, type Vector4 } from 'three'
import {
  abs,
  atan,
  attribute,
  clamp,
  cos,
  exp,
  floor,
  fract,
  length,
  max,
  mix,
  modelWorldMatrix,
  positionGeometry,
  pow,
  screenCoordinate,
  sin,
  smoothstep,
  step,
  texture,
  uv,
  varying,
  vec2,
  vec3,
  vec4,
} from 'three/tsl'
import { MeshBasicNodeMaterial, type Node } from 'three/webgpu'
import { fbm, hash, noise } from './noise'
import { facing } from './portal'
import { follow } from './uniforms'

type F = Node<'float'>
type V2 = Node<'vec2'>
type V3 = Node<'vec3'>

export interface RiftShared {
  uTime: { value: number }
  uOpen: { value: number }
  uTurb: { value: number }
  uSeed: { value: number }
}

/** The rift's edge (as the GLSL `EDGE` chunk): its outline and thin-film colors. */
function edgeOf(record: RiftShared, closed: number) {
  const time = follow<F>(record.uTime)
  const open = follow<F>(record.uOpen)
  const turb = follow<F>(record.uTurb)
  const seed = follow<F>(record.uSeed)
  // Sampling noise on the unit circle keeps the outline seamless all the way round.
  const edge = (dir: V2) => {
    const ragged = smoothstep(closed, 1, open).mul(turb)
    const slow = fbm(dir.mul(1.4).add(seed).add(time.mul(0.11)) as V2, 3, 2.07, 13.3).sub(0.5)
    const fine = noise(dir.mul(6).sub(seed).add(time.mul(0.7)) as V2).sub(0.5)
    return open.mul(slow.mul(0.55).mul(ragged).add(fine.mul(0.1).mul(ragged)).add(0.82)) as F
  }
  // Thin-film iridescence, held to the pink / violet / cyan end of the spectrum.
  const film = (at: F) => {
    const x = fract(at)
    let c = mix(vec3(1, 0.08, 0.55), vec3(0.35, 0.12, 1), smoothstep(0, 0.33, x)) as V3
    c = mix(c, vec3(0.1, 0.75, 1), smoothstep(0.33, 0.66, x)) as V3
    return mix(c, vec3(1, 0.08, 0.55), smoothstep(0.66, 1, x)) as V3
  }
  return { time, open, seed, edge, film }
}

/** The object's scale along x, as the GLSL `length(modelMatrix[0].xyz)`. */
const worldScale = () => length(modelWorldMatrix.mul(vec4(1, 0, 0, 0)).xyz) as F

export interface RiftWindowUniforms extends RiftShared {
  uR: { value: number }
  uView: { value: Texture | null }
  uViewport: { value: Vector4 }
  uLive: { value: number }
  uTint: { value: Color }
  uTintMix: { value: number }
}

/** The node (TSL) twin of `Rift`'s window: the far end live, the plasma rim and glints. */
export function windowMaterial(record: RiftWindowUniforms, closed: number, extent: number) {
  // Black until the first far view is drawn into a target.
  const placeholder = new DataTexture(new Uint8Array([0, 0, 0, 255]), 1, 1)
  placeholder.needsUpdate = true
  const { time, open, seed, edge, film } = edgeOf(record, closed)
  const R = follow<F>(record.uR)
  const viewport = follow<Node<'vec4'>>(record.uViewport)
  const live = follow<F>(record.uLive)
  const tintColor = follow<V3>(record.uTint)
  const tintMix = follow<F>(record.uTintMix)

  const p = varying(positionGeometry.xy.div(R)) as V2
  const r = length(p) as F
  const dir = p.div(max(r, 1e-4)) as V2
  const d = r.sub(edge(dir))
  const s = mix(0.45, 1, open) as F
  const inside = smoothstep(s.mul(-0.006), s.mul(0.006), d).oneMinus()
  const lens = exp(d.min(0).div(s.mul(0.05)))
  const a = atan(p.y, p.x)
  const tint = mix(
    film(a.mul(0.32).add(d.mul(1.2)).add(time.mul(0.08)) as F),
    tintColor,
    tintMix,
  ) as V3

  // The far end, sampled where this pixel is on screen. WebGPU counts screen and texture rows
  // from the top, so both agree without a flip; only the lensing's vertical push changes sign.
  const at = screenCoordinate.xy.sub(viewport.xy).div(viewport.zw) as V2
  const bent = at.sub(vec2(dir.x, dir.y.negate()).mul(lens).mul(0.012)) as V2
  const viewTexture = texture(placeholder, bent)
  const view = viewTexture.rgb as V3
  const shimmer = tint.mul(
    fbm(p.mul(2.5).add(seed).add(time.mul(0.15)) as V2, 3, 2.07, 13.3)
      .mul(0.18)
      .add(0.12),
  )
  let far = mix(shimmer, view, live) as V3
  far = mix(far, tint.mul(0.5), lens.mul(0.25)) as V3

  const plasma = noise(
    dir
      .mul(14)
      .add(vec2(time.mul(1.7), time.mul(-1.3)))
      .add(seed) as V2,
  )
    .mul(0.9)
    .add(0.55)
  const core = exp(pow(d.div(s.mul(0.02)), 2).negate()).mul(plasma)
  const glow = exp(abs(d).negate().div(s.mul(0.04))).mul(plasma)
  const halo = step(0, d)
    .mul(exp(pow(d.div(s.mul(0.2)), 2).negate()))
    .mul(0.16)

  const g = p.mul(40) as V2
  const id = floor(g) as V2
  const h = hash(id.add(seed) as V2)
  const off = vec2(hash(id.add(3.1) as V2), hash(id.add(7.7) as V2))
    .sub(0.5)
    .mul(0.6)
  const twinkle = pow(
    sin(time.mul(h.mul(5).add(2)).add(h.mul(40)))
      .mul(0.5)
      .add(0.5),
    6,
  )
  const band = exp(pow(d.sub(s.mul(0.05)).div(s.mul(0.1)), 2).negate())
  const glint = step(0.6, h)
    .mul(twinkle)
    .mul(smoothstep(0.14, 0, length(fract(g).sub(0.5).sub(off))))
    .mul(band)

  const fade = smoothstep(extent * 0.75, extent, r).oneMinus()
  const light = tint
    .mul(glow.mul(1.1).add(halo))
    .add(vec3(1).mul(core).mul(1.8))
    .add(mix(vec3(1), tint, 0.4).mul(glint).mul(2.5))
    .mul(fade) as V3
  const alpha = max(
    inside,
    clamp(core.mul(0.6).add(glow.mul(0.6)).add(halo.mul(1.2)).add(glint.mul(0.5)).mul(fade), 0, 1),
  )

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    premultipliedAlpha: true,
    depthWrite: false,
  })
  material.vertexNode = facing(positionGeometry.xy.mul(worldScale()) as V2)
  // The GLSL encodes its output itself; here the frame's output pass does, from linear light.
  material.colorNode = vec4(far.mul(inside).add(light), alpha)
  // The far end's texture: point `view.value` at the target drawn for this frame.
  return { material, view: viewTexture as unknown as { value: Texture } }
}

export interface RiftMoteUniforms extends RiftShared {
  uR: { value: number }
  uSize: { value: number }
  uTint: { value: Color }
  uTintMix: { value: number }
}

/** The node (TSL) twin of `Rift`'s glitter, drawn on `pointQuads`. */
export function riftMotesMaterial(record: RiftMoteUniforms, closed: number) {
  const { time, open, edge, film } = edgeOf(record, closed)
  const R = follow<F>(record.uR)
  const size = follow<F>(record.uSize)
  const tintColor = follow<V3>(record.uTint)
  const tintMix = follow<F>(record.uTintMix)
  const mote = attribute('aMote', 'vec3') as V3
  const kind = attribute('aKind', 'vec3') as V3

  const life = fract(mote.y.add(time.mul(mote.z))) as F
  const start = vec2(cos(mote.x), sin(mote.x)) as V2
  // Born on the rim, then shed outward (or, for a few, inward) and settling like glitter.
  const r = edge(start).add(kind.z.mul(life).mul(mix(0.4, 1, open)))
  const a = mote.x.add(life.mul(0.35))
  const p = vec2(cos(a), sin(a))
    .mul(r)
    .sub(vec2(0, life.mul(life).mul(0.3).mul(open))) as V2
  const scale = worldScale()
  const span = size.mul(scale).mul(kind.x.add(0.4))
  const offset = p.mul(R).mul(scale).add(positionGeometry.xy.mul(span)) as V2

  const fade = smoothstep(0, 0.08, life).mul(smoothstep(0.55, 1, life).oneMinus())
  const twinkle = pow(
    sin(time.mul(kind.y.mul(9).add(5)).add(mote.y.mul(60)))
      .mul(0.5)
      .add(0.5),
    3,
  )
    .mul(0.65)
    .add(0.35)
  const color = varying(
    mix(vec3(1), mix(film(kind.y), tintColor, tintMix), 0.55)
      .mul(fade)
      .mul(twinkle),
  ) as V3
  const spark = pow(smoothstep(0.5, 0, length(uv().sub(0.5))), 2)

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    blending: AdditiveBlending,
    depthWrite: false,
  })
  material.vertexNode = facing(offset)
  material.colorNode = vec4(color.mul(spark).mul(1.6), 1)
  material.toneMapped = false
  return material
}

export { pointQuads, poolMaterial } from './portal'

import {
  AdditiveBlending,
  type BufferGeometry,
  type Color,
  type InstancedBufferAttribute,
  InstancedBufferGeometry,
  PlaneGeometry,
} from 'three'
import {
  attribute,
  cameraProjectionMatrix,
  clamp,
  cos,
  exp,
  float,
  fract,
  length,
  max,
  mix,
  modelViewMatrix,
  positionGeometry,
  pow,
  sin,
  smoothstep,
  uv,
  varying,
  vec2,
  vec3,
  vec4,
} from 'three/tsl'
import { MeshBasicNodeMaterial, type Node } from 'three/webgpu'
import { fbm } from './noise'
import { follow } from './uniforms'

type F = Node<'float'>
type V2 = Node<'vec2'>
type V3 = Node<'vec3'>

/** A point `offset` (in view units) from the object's center, facing the camera: the clip
 *  position the GLSL computes as `projectionMatrix * (modelViewMatrix * origin + offset)`. */
export function facing(offset: V2) {
  const center = modelViewMatrix.mul(vec4(0, 0, 0, 1))
  return cameraProjectionMatrix.mul(center.add(vec4(offset, 0, 0)))
}

/** Rotate `p` by an angle growing toward the center: noise sampled through it spirals. */
function twirl(p: V2, r: F, k: number, t: F): V2 {
  const a = float(k).div(r.add(0.15)).add(t)
  const c = cos(a)
  const s = sin(a)
  return vec2(c.mul(p.x).add(s.mul(p.y)), s.negate().mul(p.x).add(c.mul(p.y))) as V2
}

export interface VortexUniforms {
  uTime: { value: number }
  uR: { value: number }
  uExtent: { value: number }
  uSeed: { value: number }
  uHot: { value: Color }
  uCool: { value: Color }
}

/** The node (TSL) twin of `Portal`'s vortex. */
export function vortexMaterial(record: VortexUniforms) {
  const time = follow<F>(record.uTime)
  const R = follow<F>(record.uR)
  const extent = follow<F>(record.uExtent)
  const seed = follow<F>(record.uSeed)
  const hot = follow<V3>(record.uHot)
  const cool = follow<V3>(record.uCool)

  const p = varying(positionGeometry.xy.mul(extent)) as V2
  const r = length(p) as F
  const h = 0.42
  let arms = mix(
    fbm(twirl(p, r, 2.2, time.mul(0.7)).mul(2.4).add(seed) as V2, 4, 2.03, 17.1),
    fbm(twirl(p, r, 3.6, time.mul(1.4)).mul(4.2).sub(seed) as V2, 4, 2.03, 17.1),
    0.45,
  ) as F
  arms = smoothstep(0.3, 0.85, arms) as F
  const outside = smoothstep(h - 0.012, h + 0.012, r)
  const disc = outside.mul(exp(r.sub(h).mul(-2.4))).mul(smoothstep(0.95, 1.3, r).oneMinus())
  const ring = exp(pow(r.sub(h * 1.04).div(0.022), 2).negate())
  const halo = outside.mul(exp(r.sub(h).mul(-1.7))).mul(smoothstep(1.3, 1.9, r).oneMinus())
  const pulse = sin(time.mul(1.3).add(r.mul(6)))
    .mul(0.15)
    .add(0.85)
  const heat = exp(r.sub(h).mul(-5))
  const tint = mix(cool, hot, clamp(heat, 0, 1)) as V3
  let light = tint
    .mul(disc.mul(arms).mul(3).add(halo.mul(0.4).mul(pulse)))
    .add(mix(hot, vec3(1), 0.6).mul(ring).mul(1.6)) as V3
  const inner = outside
    .oneMinus()
    .mul(pow(r.div(h), 6))
    .mul(arms)
    .mul(0.25)
  light = light.add(cool.mul(inner)) as V3
  const shadow = smoothstep(h, h * 1.8, r)
    .oneMinus()
    .mul(0.6)
  const alpha = max(
    outside.oneMinus(),
    clamp(disc.mul(arms).mul(0.7).add(shadow.mul(outside)), 0, 0.95),
  )

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    premultipliedAlpha: true,
    depthWrite: false,
  })
  material.vertexNode = facing(positionGeometry.xy.mul(extent).mul(R) as V2)
  // Light added over the scene: the GLSL adds it to display values, this to linear light, so it
  // goes in as is (converting it would wash the swirl out against a bright sky).
  material.colorNode = vec4(light, alpha)
  material.toneMapped = false
  return material
}

/**
 * Sized points for `WebGPURenderer`, which draws `Points` one pixel wide: one camera-facing quad
 * per point, instanced. `attributes` become per-instance attributes of the same names.
 */
export function pointQuads(count: number, attributes: Record<string, InstancedBufferAttribute>) {
  const quad = new PlaneGeometry(1, 1)
  const geometry = new InstancedBufferGeometry()
  geometry.index = quad.index
  geometry.setAttribute('position', quad.getAttribute('position'))
  geometry.setAttribute('uv', quad.getAttribute('uv'))
  for (const [name, attr] of Object.entries(attributes)) geometry.setAttribute(name, attr)
  geometry.instanceCount = count
  return geometry as BufferGeometry
}

export interface PortalMoteUniforms {
  uTime: { value: number }
  uR: { value: number }
  uSize: { value: number }
  uColor: { value: Color }
}

/** The node (TSL) twin of `Portal`'s drifting motes, drawn on `pointQuads`. */
export function portalMotesMaterial(record: PortalMoteUniforms) {
  const time = follow<F>(record.uTime)
  const R = follow<F>(record.uR)
  const size = follow<F>(record.uSize)
  const color = follow<V3>(record.uColor)
  const mote = attribute('aMote', 'vec3') as V3
  const life = fract(mote.y.add(time.mul(mote.z))) as F
  const r = mix(1.45, 0.44, life.mul(life)) as F
  const a = mote.x.sub(float(2.2).div(r.add(0.15))).sub(time.mul(0.7))
  const span = size.mul(life.add(0.6))
  const offset = vec2(cos(a), sin(a)).mul(r).mul(R).add(positionGeometry.xy.mul(span)) as V2
  const fade = varying(smoothstep(0, 0.25, life).mul(smoothstep(0.85, 1, life).oneMinus())) as F
  const d = length(uv().sub(0.5))

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    blending: AdditiveBlending,
    depthWrite: false,
  })
  material.vertexNode = facing(offset)
  material.colorNode = vec4(color.mul(smoothstep(0.5, 0, d)).mul(fade), 1)
  material.toneMapped = false
  return material
}

/** The node (TSL) twin of a portal's or rift's glow pooled on the ground. */
export function poolMaterial(
  record: { uColor: { value: Color }; uOpen?: { value: number } },
  strength: number,
) {
  const color = follow<V3>(record.uColor)
  const open = record.uOpen ? follow<F>(record.uOpen) : float(1)
  const r = length(uv().sub(0.5)).mul(2)
  const a = pow(max(r.oneMinus(), 0), 2.2).mul(strength).mul(open)
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    blending: AdditiveBlending,
    depthWrite: false,
  })
  // Added over the floor in linear light, as is (see the vortex).
  material.colorNode = vec4(color.mul(a), 1)
  material.toneMapped = false
  return material
}

import { dot, float, floor, fract, mix, sin, vec2 } from 'three/tsl'
import type { Node } from 'three/webgpu'

type V2 = Node<'vec2'>
type F = Node<'float'>

/** The GLSL `hash` the shader components share: a pseudo-random 0..1 per point. */
export function hash(p: V2): F {
  return fract(sin(dot(p, vec2(127.1, 311.7))).mul(43758.5453)) as F
}

/** Smooth value noise, 0..1. */
export function noise(p: V2): F {
  const i = floor(p) as V2
  const f = fract(p) as V2
  const u = f.mul(f).mul(f.mul(-2).add(3)) as V2
  const a = hash(i)
  const b = hash(i.add(vec2(1, 0)) as V2)
  const c = hash(i.add(vec2(0, 1)) as V2)
  const d = hash(i.add(vec2(1, 1)) as V2)
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y) as F
}

/** Fractal noise: `octaves` layers, each `lacunarity` times finer and shifted by `shift`. */
export function fbm(p: V2, octaves: number, lacunarity: number, shift: number): F {
  let v: F = float(0)
  let q: V2 = p
  let a = 0.5
  for (let i = 0; i < octaves; i++) {
    v = v.add(noise(q).mul(a)) as F
    q = q.mul(lacunarity).add(shift) as V2
    a *= 0.5
  }
  return v
}

import { float, uniform } from 'three/tsl'
import { Node, type NodeFrame, NodeUpdateType } from 'three/webgpu'

/** A TSL uniform that follows `entry.value` every render, so the `{ value }` records a
 *  component already updates (for its GLSL material) drive its node material too. */
export function follow<N extends Node>(entry: { value: unknown }): N {
  return uniform(entry.value as never).onRenderUpdate(() => entry.value as never) as unknown as N
}

class BeforeDraw extends Node {
  constructor(private readonly run: (frame: NodeFrame) => void) {
    super('float')
    this.updateBeforeType = NodeUpdateType.OBJECT
  }

  updateBefore(frame: NodeFrame) {
    this.run(frame)
    return true
  }

  setup() {
    return float(0)
  }
}

/**
 * A node worth 0 that runs `run` before each object using it draws: add it to anything in the
 * material to have it run. For what a uniform can't do per object, like pointing a texture node at
 * another texture (a texture node resets its own update hook when it builds).
 */
export function beforeDraw(run: (frame: NodeFrame) => void): Node<'float'> {
  return new BeforeDraw(run) as unknown as Node<'float'>
}
